  function spawnBoomerang(t,s,target){state.specialShots.push({kind:'boomerang',originKey:entityKey(t,'t'),x:t.x,y:t.y,tx:target.x,ty:target.y,phase:'out',damage:s.damage,color:s.color,speed:s.projectileSpeed||260,hits:{},life:5,trail:selectedProjectileTrail(s.copyType||t.type),tail:[]});}
