      const origin=state.towers.find(t=>entityKey(t,'t')===p.originKey);
      if(p.kind==='boomerang'){const ox=origin?.x??p.x,oy=origin?.y??p.y,arrived=moveShot(p,p.phase==='out'?p.tx:ox,p.phase==='out'?p.ty:oy,p.speed*dt);for(const e of [...state.enemies])if(Math.hypot(e.x-p.x,e.y-p.y)<e.radius+9){const k=`${entityKey(e,'e')}:${p.phase}`;if(!p.hits[k]){p.hits[k]=1;damage(e,p.damage);}}if(arrived){if(p.phase==='out')p.phase='back';else state.specialShots.splice(i,1);}continue;}
