      if(p.kind==='drone'){if(!origin){state.specialShots.splice(i,1);continue;}p.cool=Math.max(0,(p.cool||0)-dt);if(p.phase==='back'||p.cool>0){if(moveShot(p,origin.x,origin.y,p.speed*dt)){p.phase='seek';p.cool=.18;}continue;}const s=towerStats(origin),target=state.enemies.filter(e=>Math.hypot(e.x-origin.x,e.y-origin.y)<=s.range*1.25).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!target){const a=(state.time||0)*2+i;p.x=origin.x+Math.cos(a)*24;p.y=origin.y+Math.sin(a)*24;continue;}moveShot(p,target.x,target.y,p.speed*dt);if(Math.hypot(target.x-p.x,target.y-p.y)<target.radius+7){damage(target,s.damage);p.phase='back';p.cool=.28;}continue;}
