  function kill(e){const i=state.enemies.indexOf(e);if(i<0)return;state.enemies.splice(i,1);state.stats.kills++;if(persistentRewardsAllowed())saved.enemyKills[e.type]=(saved.enemyKills[e.type]||0)+1;if(e.split){state.enemies.push(makeEnemy('runner',e.x,e.y,e.seg,.48),makeEnemy('runner',e.x,e.y,e.seg,.48));state.effects.push({x:e.x,y:e.y,life:.55,color:'#ff75a5'});}if(enemies[e.type]?.hatch){for(let n=0;n<3;n++){const hatchling=makeEnemy('crawler',e.x+(Math.random()-.5)*12,e.y+(Math.random()-.5)*12,e.seg,.42);hatchling.reward=Math.max(1,Math.round(hatchling.reward*.45));state.enemies.push(hatchling);}state.effects.push({x:e.x,y:e.y,life:.65,color:'#9be678'});}state.money+=e.reward;treasureReward(e);state.score+=e.boss?500:e.type==='crawler'?50:80;if(state.selectedEnemy===e){state.selectedEnemy=null;ui.enemyInfo.classList.add('hidden');}playTone(e.boss?90:160,.04,'sine',.085,0,'combat');updateUI();}
  function damageHeart(e){const s=enemies[e.type],amount=s.leakDamage;state.stats.enemiesLeaked++;if(state.invincible){announce(`Invincible · blocked ${amount} damage`);playSoundEffect('shield');return;}if(s.stealCredits){const stolen=Math.min(state.money,s.stealCredits);state.money-=stolen;announce(`${s.name} stole ${stolen} credits`);}for(let n=0;n<6;n++)state.effects.push({x:path.at(-1).x+(Math.random()-.5)*35,y:path.at(-1).y+(Math.random()-.5)*35,life:.35+Math.random()*.35,color:'#ff6b55'});shakeField();playSoundEffect('heart');if(s.livesDamage){const lost=Math.min(state.lives,s.livesDamage);state.stats.damageTaken+=amount;state.stats.livesLost+=lost;state.lives-=lost;if(state.lives>0){state.health=100;announce(`${s.name} destroyed ${lost} lives · ${state.lives} remaining`);playTone(75,.35,'sawtooth',.15);}else{state.health=0;endGame(false);}updateUI();return;}state.stats.damageTaken+=amount;state.health-=amount;if(state.health<=0){state.lives--;state.stats.livesLost++;if(state.lives>0){state.health=100;announce(`Life lost · ${state.lives} remaining · Health restored`);playTone(75,.35,'sawtooth',.15);}else{state.health=0;endGame(false);}}else if(!s.stealCredits)announce(`${s.name} dealt ${amount} damage`);updateUI();}
