      const wall=state.towers.find(t=>!towerRiftPhased(t)&&towers[t.type]?.wall&&Math.hypot(e.x-t.x,e.y-t.y)<towerStats(t).range+e.radius);
      if(wall){ensureWall(wall);wall.wallHp-=(5+s.leakDamage*.22)*dt;if(Math.random()<dt*4)state.effects.push({x:wall.x+(Math.random()-.5)*12,y:wall.y+(Math.random()-.5)*12,life:.25,color:'#9fc77b'});if(wall.wallHp<=0){const wi=state.towers.indexOf(wall);if(wi>=0)state.towers.splice(wi,1);state.effects.push({x:wall.x,y:wall.y,life:.8,color:'#ff9e58'});if(state.selectedTower===wall){clearSelections();idleInfo();}announce('Ancient Oak destroyed');}continue;}
      const dest=path[e.seg+1];if(!dest)continue;const d=Math.hypot(dest.x-e.x,dest.y-e.y),bannerSpeed=state.enemies.some(other=>other!==e&&enemies[other.type]?.banner&&Math.hypot(other.x-e.x,other.y-e.y)<110)?1.22:1,enrage=s.enrage&&e.hp/e.maxHp<.5?1.55:1,eclipseSpeed=s.eclipse&&!e.phaseArmored?1.38:1,step=e.speed*bannerSpeed*enrage*eclipseSpeed*(e.slow>0?(e.boss?.75:.55):1)*dt;
