  async function deleteCustomMap(map){if(map.cloudId&&supabaseClient&&saved.account){const tombstone={...map,deleted:true,deletedAt:Date.now(),archived:false,showOnHome:false,visibility:'private'},{error}=await supabaseClient.from('custom_maps').update({visibility:'private',map_data:tombstone,archived_at:null,deleted_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',map.cloudId).eq('owner_id',saved.account.id);if(error){alert(`Could not delete this map everywhere: ${cloudUnavailable(error)}`);return false;}}saved.customMaps=(saved.customMaps||[]).filter(item=>item.id!==map.id);cloudPublicMaps=cloudPublicMaps.filter(item=>String(item.id)!==String(map.cloudId||map.id));delete maps[`custom_${map.id}`];if(selectedMap===`custom_${map.id}`)selectedMap='meadow';hydrateCustomMaps();save();ensureCustomMapCards();renderMyMaps();renderPublicMaps();return true;}
  async function syncCustomMap(map){if(!supabaseClient||!saved.account)return;const payload={owner_id:saved.account.id,name:map.name,description:map.description||'',difficulty:map.difficulty||'Unrated',visibility:map.visibility,collaboration_mode:map.collabMode||'owner',share_code:map.customCode||null,map_data:map,archived_at:map.archived?new Date(map.archivedAt||Date.now()).toISOString():null,deleted_at:map.deleted?new Date(map.deletedAt||Date.now()).toISOString():null};let result;if(map.cloudId)result=await supabaseClient.from('custom_maps').update(payload).eq('id',map.cloudId).select('id').single();else result=await supabaseClient.from('custom_maps').insert(payload).select('id').single();if(result.error){ui.creatorHint.textContent=`Saved locally. Online sharing: ${cloudUnavailable(result.error)}`;return;}map.cloudId=result.data.id;if(map.collabMode==='specific'){const names=map.collaborators||[],{data:people}=names.length?await supabaseClient.from('profiles').select('id,username').in('username',names):{data:[]};await supabaseClient.from('map_collaborators').delete().eq('map_id',map.cloudId);if(people?.length)await supabaseClient.from('map_collaborators').insert(people.map(p=>({map_id:map.cloudId,user_id:p.id})));}save();}
