    if(name==='sell'){tone(360,.06,'triangle',.045);tone(240,.08,'triangle',.038,.04);tone(170,.1,'sine',.026,.085);return;}
    if(name==='upgrade'){tone(520,.06,'triangle',.045);tone(720,.07,'triangle',.04,.045);tone(960,.1,'sine',.035,.09);return;}
    if(name==='stat'){tone(760,.06,'sine',.04);tone(1020,.08,'triangle',.035,.04);tone(1280,.12,'sine',.03,.09);return;}
    if(name==='specialize'){tone(440,.18,'triangle',.045);tone(660,.2,'triangle',.04,.035);tone(880,.24,'sine',.035,.07);return;}
